import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"谬谏","description":"","frontmatter":{"title":"谬谏","date":"2026-11-24T00:00:00.000Z","seq":37,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"东方朔","source_book":"楚辞","prev":{"text":"哀命","link":"/blogs/楚辞/哀命.html"},"next":{"text":"哀时命","link":"/blogs/楚辞/哀时命.html"}},"headers":[],"relativePath":"blogs/楚辞/谬谏.md","filePath":"blogs/楚辞/谬谏.md"}'),o={name:"blogs/楚辞/谬谏.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="谬谏" tabindex="-1">谬谏 <a class="header-anchor" href="#谬谏" aria-label="Permalink to &quot;谬谏&quot;">​</a></h1><p class="poem-meta">先秦 · 东方朔　·　七谏</p><div class="poem"><p class="poem-stanza">怨灵修之浩荡兮，夫何执操之不固？</p><p class="poem-stanza">悲太山之为隍兮，孰江河之可涸？</p><p class="poem-stanza">愿承闲而效志兮，恐犯忌而干讳。</p><p class="poem-stanza">卒抚情以寂寞兮，然怊怅而自悲。</p><p class="poem-stanza">玉与石其同匮兮，贯鱼眼与珠玑。</p><p class="poem-stanza">驽骏杂而不分兮，服罢牛而骖骥。</p><p class="poem-stanza">年滔滔而自远兮，寿冉冉而愈衰。</p><p class="poem-stanza">心悇憛而烦冤兮，蹇超摇而无冀。</p><p class="poem-stanza">固时俗之工巧兮，灭规矩而改错。</p><p class="poem-stanza">郤骐骥而不乘兮，策驽骀而取路。</p><p class="poem-stanza">当世岂无骐骥兮，诚无王良之善驭。</p><p class="poem-stanza">见执辔者非其人兮，故驹跳而远去。</p><p class="poem-stanza">不量凿而正枘兮，恐矩矱之不同。</p><p class="poem-stanza">不论世而高举兮，恐操行之不调。</p><p class="poem-stanza">弧弓弛而不张兮，孰云知其所至？</p><p class="poem-stanza">无倾危之患难兮，焉知贤士之所死？</p><p class="poem-stanza">俗推佞而进富兮，节行张而不著。</p><p class="poem-stanza">贤良蔽而不群兮，朋曹比而党誉。</p><p class="poem-stanza">邪说饰而多曲兮，正法弧而不公。</p><p class="poem-stanza">直士隐而避匿兮，谗谀登乎明堂。</p><p class="poem-stanza">弃彭咸之娱乐兮，灭巧倕之绳墨。</p><p class="poem-stanza">菎蕗杂于黀蒸兮，机蓬矢以射革。</p><p class="poem-stanza">驾蹇驴而无策兮，又何路之能极？</p><p class="poem-stanza">以直鍼而为钓兮，又何鱼之能得？</p><p class="poem-stanza">伯牙之绝弦兮，无锺子期而听之。</p><p class="poem-stanza">和抱璞而泣血兮，安得良工而剖之？</p><p class="poem-stanza">同音者相和兮，同类者相似。</p><p class="poem-stanza">飞鸟号其群兮，鹿鸣求其友。</p><p class="poem-stanza">故叩宫而宫应兮，弹角而角动。</p><p class="poem-stanza">虎啸而谷风至兮，龙举而景云往。</p><p class="poem-stanza">音声之相和兮，言物类之相感也。</p><p class="poem-stanza">夫方圜之异形兮，势不可以相错。</p><p class="poem-stanza">列子隐身而穷处兮，世莫可以寄讬。</p><p class="poem-stanza">众鸟皆有行列兮，凤独翔翔而无所薄。</p><p class="poem-stanza">经浊世而不得志兮，愿侧身岩穴而自讬。</p><p class="poem-stanza">欲阖口而无言兮，尝被君之厚德。</p><p class="poem-stanza">独便悁而怀毒兮，愁郁郁之焉极？</p><p class="poem-stanza">念三年之积思兮，愿壹见而陈辞。</p><p class="poem-stanza">不及君而骋说兮，世孰可为明之？</p><p class="poem-stanza">身寝疾而日愁兮，情沉抑而不扬。</p><p class="poem-stanza">众人莫可与论道兮，悲精神之不通。</p><p class="poem-stanza">乱曰：鸾皇孔凤日以远兮，畜凫驾鹅。</p><p class="poem-stanza">鸡鹜满堂坛兮，鼉黽游乎华池。</p><p class="poem-stanza">要褭奔亡兮，腾驾橐驼。</p><p class="poem-stanza">铅刀进御兮，遥弃太阿。</p><p class="poem-stanza">拔搴玄芝兮，列树芋荷。</p><p class="poem-stanza">橘柚萎枯兮，苦李旖旎。</p><p class="poem-stanza">甂瓯登于明堂兮，周鼎潜潜乎深渊。</p><p class="poem-stanza">自古而固然兮，吾又何怨乎今之人。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
